-- V25__fix_world_cup_fairplay_and_standings.sql
-- 1. Ensure FIFA World Cup 2026 competition has canonical name, slug and tournament format
UPDATE competitions SET name = 'FIFA World Cup 2026', external_id = 'fifa.world', format_type = 'TOURNAMENT' WHERE name ILIKE '%World%' OR name ILIKE '%Mundial%' OR external_id = 'fifa.world';

