-- 3. Recalculate fair_play_points in group_standings from matches
UPDATE group_standings gs
SET fair_play_points = COALESCE((
    SELECT SUM(CASE WHEN m.home_team_id = gs.team_id THEN m.home_fair_play ELSE m.away_fair_play END)
    FROM matches m
    WHERE (m.home_team_id = gs.team_id OR m.away_team_id = gs.team_id)
      AND m.round = 'group'
      AND m.finished = true
), 0);
